SELECT eo.id, eo.order_no AS orderNo, eo.user_id AS userId, u.username, eo.product_id AS productId, eo.product_name AS productName, eo.quantity, eo.points_required AS pointsRequired, eo.total_points AS totalPoints, eo.order_status AS orderStatus, eo.receiver_name AS receiverName, eo.receiver_phone AS receiverPhone, eo.receiver_address AS receiverAddress, eo.express_company AS expressCompany, eo.express_no AS expressNo, eo.remark, eo.create_time AS createTime, eo.update_time AS updateTime FROM exchange_order eo LEFT JOIN user u ON eo.user_id = u.id
AND eo.user_id = #{query.userId}
AND eo.order_status = #{query.orderStatus}
AND eo.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND eo.create_time >= #{query.startTime}
AND eo.create_time <= #{query.endTime}
ORDER BY eo.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM exchange_order eo


